import { MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, mix, smoothstep, uv } from 'three/tsl';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const primitiveResults = [];
  const ownedResources = [];
  const timelines = [];

  const colors =
    config.intent?.visualSpec?.colors ?? {
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      surface: '#0b0b10'
    };

  const hexToVec3 = (hex) => {
    const value = String(hex).replace('#', '');
    const r = parseInt(value.slice(0, 2), 16) / 255;
    const g = parseInt(value.slice(2, 4), 16) / 255;
    const b = parseInt(value.slice(4, 6), 16) / 255;
    return vec3(r, g, b);
  };

  const makeGradientMaterial = (topHex, bottomHex) => {
    const material = new MeshBasicNodeMaterial();
    const y = smoothstep(0.05, 0.95, uv().y);
    material.colorNode = mix(
      hexToVec3(bottomHex),
      hexToVec3(topHex),
      y
    );
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = makeGradientMaterial(colors.ink, colors.surface);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  ownedResources.push(backdropGeometry, backdropMaterial);

  const surfaceGeometry = new PlaneGeometry(4.85, 3.15);
  const surfaceMaterial = makeGradientMaterial(colors.ink, colors.surface);
  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.position.set(0, 0, -1.35);
  root.add(surface);
  ownedResources.push(surfaceGeometry, surfaceMaterial);

  const imageGeometry = new PlaneGeometry(4.2, 2.625);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: colors.paper
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.set(0, 0, -0.15);
  root.add(imagePlane);
  ownedResources.push(imageGeometry, imageMaterial);

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });

  const topEdgeGeometry = new BoxGeometry(4.2, 0.025, 0.025);
  const topEdge = new Mesh(topEdgeGeometry, edgeMaterial);
  topEdge.position.set(0, 1.34, 0.02);
  root.add(topEdge);
  ownedResources.push(topEdgeGeometry);

  const sideEdgeGeometry = new BoxGeometry(0.025, 0.42, 0.025);
  const sideEdge = new Mesh(sideEdgeGeometry, edgeMaterial);
  sideEdge.position.set(-2.08, -1.1, 0.02);
  root.add(sideEdge);
  ownedResources.push(sideEdgeGeometry, edgeMaterial);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!root.parent && root.userData.cleaned) {
        texture.dispose?.();
        return;
      }

      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      ownedResources.push(texture);
    });
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    for (const resource of ownedResources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}

export default createNode;
